"""Renders the screenshots and GIFs of the wiki by running the examples in tools/wiki/text.

An example takes part when its first line is a media tag, which wiki.py hides from the page:

  ;media still drawing/rect.png          Runs the example until it reaches WaitKey and saves that frame.
  ;media gif drawing/spin.gif 60 20      Saves 60 frames, one per Flip, and joins them into a 20 fps GIF.

The path is relative to docs/wiki/media. Examples that animate should step by frame count and not by MilliSecs, so
that every run gives the same picture. Needs blitzcc, clang, xvfb-run and ffmpeg.

  media.py [--blitzcc PATH] [--only SUBSTRING]
"""
import argparse
import os
import re
import shutil
import sys
import tempfile

HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, HERE)
import wiki  # noqa: E402
sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), ".."))
import procutil  # noqa: E402

TAG = re.compile(r"^;media (still|gif) (\S+)(?: (\d+) (\d+))?\s*$")


def instrument(src, kind, out, frames):
    lines = src.split("\n")[1:]
    if kind == "still":
        code, hit = [], False
        for line in lines:
            if re.match(r"^\s*WaitKey\b", line, re.I):
                code.append('SaveBuffer(FrontBuffer(), "%s") : End' % out)
                hit = True
            else:
                code.append(line)
        if not hit:
            code.append('SaveBuffer(FrontBuffer(), "%s")' % out)
        return "\n".join(code)
    code = ["Global WikiFrameN% = 0"]
    for line in lines:
        code.append(re.sub(r"^(\s*Flip\b.*)$", r"\1 : WikiFrame()", line, flags=re.I))
    code.append('Function WikiFrame()\n  SaveBuffer(FrontBuffer(), "%s/f" + Right("0000" + WikiFrameN, 4) + ".png")\n'
                "  WikiFrameN = WikiFrameN + 1\n  If WikiFrameN >= %d Then End\nEnd Function" % (out, frames))
    return "\n".join(code)


def render(blitzcc, kind, rel, frames, fps, src):
    dest = os.path.join(wiki.WIKI, "media", rel)
    os.makedirs(os.path.dirname(dest), exist_ok=True)
    env = dict(os.environ, XDG_RUNTIME_DIR=tempfile.mkdtemp())
    with tempfile.TemporaryDirectory() as d:
        out = dest if kind == "still" else d
        path = os.path.join(d, "example.bb")
        with open(path, "w", encoding="utf-8") as f:
            f.write(instrument(src, kind, out, frames))
        exe = os.path.join(d, "example")
        r = procutil.run([blitzcc, "+q", "-o", exe, path], capture_output=True, text=True)
        if r.returncode != 0:
            return r.stdout + r.stderr
        r = procutil.run(["xvfb-run", "-a", exe], capture_output=True, text=True, env=env, timeout=120)
        if kind == "still":
            return "" if os.path.exists(dest) else "no screenshot was saved\n" + r.stdout + r.stderr
        if not os.path.exists(os.path.join(d, "f%04d.png" % (frames - 1))):
            return "only %d frames were saved\n%s" % (len([n for n in os.listdir(d) if n.startswith("f")]), r.stderr)
        procutil.run(["ffmpeg", "-v", "error", "-y", "-framerate", str(fps), "-i", os.path.join(d, "f%04d.png"),
                        "-vf", "split[a][b];[a]palettegen=max_colors=64[p];[b][p]paletteuse=dither=none", dest],
                       check=True)
    return ""


def main():
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("--blitzcc", default=shutil.which("blitzcc") or os.path.join(wiki.ROOT, "build", "code_compiler",
                                                                                  "blitzcc"))
    ap.add_argument("--only", default="")
    args = ap.parse_args()
    failed = 0
    for c in wiki.load():
        for m in re.finditer(r"```blitzbasic\n(.*?)```", c.text, re.S):
            src = m.group(1)
            tag = TAG.match(src.split("\n")[0])
            if not tag or args.only not in tag.group(2):
                continue
            kind, rel = tag.group(1), tag.group(2)
            err = render(args.blitzcc, kind, rel, int(tag.group(3) or 0), int(tag.group(4) or 20), src)
            print("%s %s %s" % ("FAIL" if err else "ok  ", c.name, rel))
            if err:
                failed += 1
                print(err, file=sys.stderr)
    return 1 if failed else 0


if __name__ == "__main__":
    sys.exit(main())
